  1	package com.pousadamareal.reservas.service;
  2	
  3	import com.pousadamareal.reservas.domain.*;
  4	import com.pousadamareal.reservas.dto.*;
  5	import com.pousadamareal.reservas.util.PricingCalculator;
  6	
  7	import java.math.BigDecimal;
  8	import java.time.LocalDate;
  9	import java.util.*;
 10	import java.util.stream.Collectors;
 11	
 12	public class ReservationService {
 13	    private static final List<Room> ROOMS = List.of(
 14	        new Room(101, RoomType.STANDARD, 2, new BigDecimal("249.90")),
 15	        new Room(102, RoomType.STANDARD, 2, new BigDecimal("249.90")),
 16	        new Room(201, RoomType.DELUXE, 3, new BigDecimal("389.90")),
 17	        new Room(202, RoomType.DELUXE, 3, new BigDecimal("389.90")),
 18	        new Room(301, RoomType.SUITE, 4, new BigDecimal("579.90"))
 19	    );
 20	
 21	    private final Map<Long, Reservation> reservations = new HashMap<>();
 22	    private final List<Message> messages = new ArrayList<>();
 23	    private long reservationIdCounter = 1;
 24	    private long messageIdCounter = 1;
 25	
 26	    public List<RoomResponse> getAllRooms() {
 27	        return ROOMS.stream()
 28	            .map(room -> {
 29	                RoomResponse response = new RoomResponse();
 30	                response.number = room.getNumber();
 31	                response.type = room.getType().getValue();
 32	                response.capacity = room.getCapacity();
 33	                response.nightlyRate = room.getNightlyRate();
 34	                return response;
 35	            })
 36	            .collect(Collectors.toList());
 37	    }
 38	
 39	    public Room getRoomByNumber(int roomNumber) {
 40	        return ROOMS.stream()
 41	            .filter(room -> room.getNumber() == roomNumber)
 42	            .findFirst()
 43	            .orElse(null);
 44	    }
 45	
 46	    public ReservationResponse createReservation(CreateReservationRequest request) {
 47	        Room room = getRoomByNumber(request.roomNumber);
 48	        if (room == null) {
 49	            throw new ApiException(404, "ROOM_NOT_FOUND", "Room not found");
 50	        }
 51	
 52	        if (request.checkIn.isAfter(request.checkOut) || request.checkIn.equals(request.checkOut)) {
 53	            throw new ApiException(400, "INVALID_REQUEST", "Check-out must be after check-in");
 54	        }
 55	
 56	        if (request.guests < 1) {
 57	            throw new ApiException(400, "INVALID_REQUEST", "At least one guest is required");
 58	        }
 59	
 60	        if (request.guests > room.getCapacity()) {
 61	            throw new ApiException(422, "CAPACITY_EXCEEDED", "Too many guests for this room");
 62	        }
 63	
 64	        if (isRoomUnavailable(request.roomNumber, request.checkIn, request.checkOut)) {
 65	            throw new ApiException(409, "ROOM_UNAVAILABLE", "Room is not available for these dates");
 66	        }
 67	
 68	        RatePlan ratePlan;
 69	        try {
 70	            ratePlan = RatePlan.fromString(request.ratePlan);
 71	        } catch (IllegalArgumentException e) {
 72	            throw new ApiException(400, "INVALID_REQUEST", "Invalid rate plan");
 73	        }
 74	
 75	        long nights = PricingCalculator.calculateNights(request.checkIn, request.checkOut);
 76	        BigDecimal subtotal = PricingCalculator.calculateSubtotal(room.getNightlyRate(), request.checkIn, request.checkOut);
 77	        BigDecimal discount = PricingCalculator.calculateDiscount(subtotal, ratePlan == RatePlan.NON_REFUNDABLE);
 78	        BigDecimal total = PricingCalculator.calculateTotal(subtotal, discount);
 79	
 80	        long id = reservationIdCounter++;
 81	        Reservation reservation = new Reservation(
 82	            id, request.roomNumber, request.guestName, request.guestEmail, request.guestCpf,
 83	            request.checkIn, request.checkOut, request.guests, ratePlan, nights, subtotal, discount, total
 84	        );
 85	
 86	        reservations.put(id, reservation);
 87	        return mapReservationToResponse(reservation);
 88	    }
 89	
 90	    public ReservationResponse getReservation(long id) {
 91	        Reservation reservation = reservations.get(id);
 92	        if (reservation == null) {
 93	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found");
 94	        }
 95	        return mapReservationToResponse(reservation);
 96	    }
 97	
 98	    public ReservationResponse confirmReservation(long id, BigDecimal amountPaid) {
 99	        Reservation reservation = reservations.get(id);
100	        if (reservation == null) {
101	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found");
102	        }
103	
104	        if (reservation.getStatus() != ReservationStatus.PENDING) {
105	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Can only confirm pending reservations");
106	        }
107	
108	        reservation.confirm(amountPaid);
109	
110	        String comprovante = generateComprovante(reservation);
111	        sendEmail(reservation.getGuestEmail(),
112	                 "Reserva confirmada - Pousada Maré Alta",
113	                 generateConfirmationEmailBody(reservation, comprovante));
114	
115	        return mapReservationToResponse(reservation);
116	    }
117	
118	    public ReservationResponse checkIn(long id) {
119	        Reservation reservation = reservations.get(id);
120	        if (reservation == null) {
121	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found");
122	        }
123	
124	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
125	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Can only check in confirmed reservations");
126	        }
127	
128	        reservation.checkIn();
129	        return mapReservationToResponse(reservation);
130	    }
131	
132	    public DocumentResponse checkOut(long id) {
133	        Reservation reservation = reservations.get(id);
134	        if (reservation == null) {
135	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found");
136	        }
137	
138	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
139	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Can only check out reservations that are checked in");
140	        }
141	
142	        reservation.checkOut();
143	        return mapReservationToDocument(reservation);
144	    }
145	
146	    public ReservationResponse cancelReservation(long id) {
147	        Reservation reservation = reservations.get(id);
148	        if (reservation == null) {
149	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found");
150	        }
151	
152	        ReservationStatus status = reservation.getStatus();
153	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
154	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Can only cancel pending or confirmed reservations");
155	        }
156	
157	        BigDecimal refund = BigDecimal.ZERO;
158	        if (status == ReservationStatus.CONFIRMED) {
159	            if (reservation.getRatePlan() == RatePlan.STANDARD) {
160	                refund = reservation.getAmountPaid();
161	            }
162	        }
163	
164	        reservation.cancel(refund);
165	        return mapReservationToResponse(reservation);
166	    }
167	
168	    public DocumentResponse getDocument(long id) {
169	        Reservation reservation = reservations.get(id);
170	        if (reservation == null) {
171	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found");
172	        }
173	
174	        if (reservation.getStatus() == ReservationStatus.PENDING) {
175	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Cannot get document for pending reservations");
176	        }
177	
178	        return mapReservationToDocument(reservation);
179	    }
180	
181	    public List<MessageResponse> getMessages() {
182	        return messages.stream()
183	            .map(msg -> {
184	                MessageResponse response = new MessageResponse();
185	                response.id = msg.getId();
186	                response.channel = msg.getChannel();
187	                response.to = msg.getTo();
188	                response.subject = msg.getSubject();
189	                response.body = msg.getBody();
190	                return response;
191	            })
192	            .collect(Collectors.toList());
193	    }
194	
195	    private boolean isRoomUnavailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
196	        return reservations.values().stream()
197	            .filter(r -> r.getRoomNumber() == roomNumber)
198	            .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
199	            .anyMatch(r -> datesOverlap(r.getCheckIn(), r.getCheckOut(), checkIn, checkOut));
200	    }
201	
202	    private boolean datesOverlap(LocalDate start1, LocalDate end1, LocalDate start2, LocalDate end2) {
203	        return start1.isBefore(end2) && end1.isAfter(start2);
204	    }
205	
206	    private ReservationResponse mapReservationToResponse(Reservation reservation) {
207	        ReservationResponse response = new ReservationResponse();
208	        response.id = reservation.getId();
209	        response.roomNumber = reservation.getRoomNumber();
210	        response.guestName = reservation.getGuestName();
211	        response.guestEmail = reservation.getGuestEmail();
212	        response.guestCpf = reservation.getGuestCpf();
213	        response.checkIn = reservation.getCheckIn();
214	        response.checkOut = reservation.getCheckOut();
215	        response.guests = reservation.getGuests();
216	        response.ratePlan = reservation.getRatePlan().getValue();
217	        response.nights = reservation.getNights();
218	        response.subtotal = reservation.getSubtotal();
219	        response.discount = reservation.getDiscount();
220	        response.total = reservation.getTotal();
221	        response.status = reservation.getStatus().getValue();
222	        response.amountPaid = reservation.getAmountPaid();
223	        response.refund = reservation.getRefund();
224	        return response;
225	    }
226	
227	    private DocumentResponse mapReservationToDocument(Reservation reservation) {
228	        Room room = getRoomByNumber(reservation.getRoomNumber());
229	        DocumentResponse response = new DocumentResponse();
230	        response.title = "Comprovante de reserva";
231	        response.reservationId = reservation.getId();
232	        response.guestName = reservation.getGuestName();
233	        response.guestCpf = reservation.getGuestCpf();
234	        response.roomNumber = reservation.getRoomNumber();
235	        response.roomType = room.getType().getValue();
236	        response.checkIn = reservation.getCheckIn();
237	        response.checkOut = reservation.getCheckOut();
238	        response.nights = reservation.getNights();
239	        response.subtotal = reservation.getSubtotal();
240	        response.discount = reservation.getDiscount();
241	        response.total = reservation.getTotal();
242	        return response;
243	    }
244	
245	    private String generateComprovante(Reservation reservation) {
246	        Room room = getRoomByNumber(reservation.getRoomNumber());
247	        StringBuilder sb = new StringBuilder();
248	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
249	        sb.append("Hóspede: ").append(reservation.getGuestName())
250	            .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
251	        sb.append("Quarto: ").append(room.getNumber())
252	            .append(" (").append(room.getType().getValue()).append(")\n");
253	        sb.append("Entrada: ").append(formatDate(reservation.getCheckIn()))
254	            .append(" | Saída: ").append(formatDate(reservation.getCheckOut()))
255	            .append(" | ").append(reservation.getNights())
256	            .append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
257	        sb.append("Diárias: ").append(formatCurrency(reservation.getSubtotal())).append("\n");
258	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
259	            sb.append("Desconto: ").append(formatCurrency(reservation.getDiscount())).append("\n");
260	        }
261	        sb.append("Total: ").append(formatCurrency(reservation.getTotal()));
262	        return sb.toString();
263	    }
264	
265	    private String generateConfirmationEmailBody(Reservation reservation, String comprovante) {
266	        StringBuilder sb = new StringBuilder();
267	        sb.append("Olá, ").append(reservation.getGuestName()).append("!\n\n");
268	        sb.append("Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n");
269	        sb.append(comprovante).append("\n\n");
270	        sb.append("A entrada é a partir das 14h, e a saída, até as 12h.\n");
271	        sb.append("Até breve!");
272	        return sb.toString();
273	    }
274	
275	    private void sendEmail(String to, String subject, String body) {
276	        long id = messageIdCounter++;
277	        Message message = new Message(id, "EMAIL", to, subject, body);
278	        messages.add(message);
279	    }
280	
281	    private String formatDate(LocalDate date) {
282	        return String.format("%02d/%02d/%d", date.getDayOfMonth(), date.getMonthValue(), date.getYear());
283	    }
284	
285	    private String formatCurrency(BigDecimal amount) {
286	        return String.format("R$ %,.2f", amount).replace(",", "X").replace(".", ",").replace("X", ".");
287	    }
288	
289	    private String formatCpf(String cpf) {
290	        if (cpf == null || cpf.length() != 11) {
291	            return cpf;
292	        }
293	        return String.format("%s.%s.%s-%s",
294	            cpf.substring(0, 3),
295	            cpf.substring(3, 6),
296	            cpf.substring(6, 9),
297	            cpf.substring(9, 11));
298	    }
299	
300	    public String generateOccupancyReport(LocalDate date) {
301	        StringBuilder sb = new StringBuilder();
302	        sb.append("Pousada Maré Alta,occupancy,").append(formatDateForReport(date)).append("\n");
303	        sb.append("room,type,reservation,check_in,check_out\n");
304	
305	        List<Reservation> occupiedReservations = reservations.values().stream()
306	            .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
307	            .filter(r -> r.getStatus() == ReservationStatus.CONFIRMED ||
308	                        r.getStatus() == ReservationStatus.CHECKED_IN ||
309	                        r.getStatus() == ReservationStatus.CHECKED_OUT)
310	            .filter(r -> !r.getCheckIn().isAfter(date) && r.getCheckOut().isAfter(date))
311	            .sorted(Comparator.comparingInt(Reservation::getRoomNumber))
312	            .collect(Collectors.toList());
313	
314	        for (Reservation reservation : occupiedReservations) {
315	            Room room = getRoomByNumber(reservation.getRoomNumber());
316	            sb.append(room.getNumber()).append(",")
317	              .append(room.getType().getValue()).append(",")
318	              .append(reservation.getId()).append(",")
319	              .append(formatDateForReport(reservation.getCheckIn())).append(",")
320	              .append(formatDateForReport(reservation.getCheckOut())).append("\n");
321	        }
322	
323	        sb.append("total,").append(occupiedReservations.size()).append("/").append(ROOMS.size()).append("\n");
324	        return sb.toString();
