388	              .append(formatDateForReport(reservation.getCheckIn())).append(",")
389	              .append(formatDateForReport(reservation.getCheckOut())).append(",")
390	              .append(reservation.getGuests()).append(",")
391	              .append(reservation.getNights()).append(",")
392	              .append(formatAmountForReport(tax)).append("\n");
393	            totalTax = totalTax.add(tax);
394	        }
395	
396	        sb.append("total,").append(formatAmountForReport(totalTax)).append("\n");
397	        return sb.toString();
398	    }
399	
400	    public String generateRatePlansReport(String month) {
401	        StringBuilder sb = new StringBuilder();
402	        sb.append("Pousada Maré Alta,rate-plans,").append(month).append("\n");
403	        sb.append("rate_plan,reservations,amount\n");
404	
405	        LocalDate monthStart = LocalDate.parse(month + "-01");
406	
407	        Map<RatePlan, Long> reservationCounts = new HashMap<>();
408	        Map<RatePlan, BigDecimal> amounts = new HashMap<>();
409	
410	        for (RatePlan plan : RatePlan.values()) {
411	            reservationCounts.put(plan, 0L);
412	            amounts.put(plan, BigDecimal.ZERO);
413	        }
414	
415	        List<Reservation> monthReservations = reservations.values().stream()
416	            .filter(r -> r.getCheckIn().getYear() == monthStart.getYear() &&
417	                        r.getCheckIn().getMonthValue() == monthStart.getMonthValue())
418	            .filter(r -> r.getStatus() == ReservationStatus.CONFIRMED ||
419	                        r.getStatus() == ReservationStatus.CHECKED_IN ||
420	                        r.getStatus() == ReservationStatus.CHECKED_OUT ||
421	                        (r.getStatus() == ReservationStatus.CANCELLED && r.getRatePlan() == RatePlan.NON_REFUNDABLE))
422	            .collect(Collectors.toList());
423	
424	        for (Reservation reservation : monthReservations) {
425	            RatePlan plan = reservation.getRatePlan();
426	            reservationCounts.put(plan, reservationCounts.get(plan) + 1);
427	
428	            BigDecimal amount = reservation.getAmountPaid().subtract(
429	                reservation.getRefund() != null ? reservation.getRefund() : BigDecimal.ZERO
430	            );
431	            amounts.put(plan, amounts.get(plan).add(amount));
432	        }
433	
434	        BigDecimal totalCount = BigDecimal.ZERO;
435	        BigDecimal totalAmount = BigDecimal.ZERO;
436	
437	        for (RatePlan plan : RatePlan.values()) {
438	            long count = reservationCounts.get(plan);
439	            BigDecimal amount = amounts.get(plan);
440	            sb.append(plan.getValue()).append(",")
441	              .append(count).append(",")
442	              .append(formatAmountForReport(amount)).append("\n");
443	            totalCount = totalCount.add(new BigDecimal(count));
444	            totalAmount = totalAmount.add(amount);
445	        }
446	
447	        sb.append("total,").append(totalCount.toPlainString()).append(",")
448	          .append(formatAmountForReport(totalAmount)).append("\n");
449	        return sb.toString();
450	    }
451	
452	    private String formatDateForReport(LocalDate date) {
453	        return date.toString();
454	    }
455	
456	    private String formatAmountForReport(BigDecimal amount) {
457	        return amount.toPlainString();
458	    }
459	}

