     1	package com.pousadamareal.reservas.util;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	import java.time.YearMonth;
     7	
     8	public class PricingCalculator {
     9	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    10	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = new BigDecimal("0.15");
    11	    private static final int SCALE = 2;
    12	
    13	    public static boolean isHighSeason(LocalDate date) {
    14	        int month = date.getMonthValue();
    15	        int day = date.getDayOfMonth();
    16	
    17	        // July (7)
    18	        if (month == 7) return true;
    19	
    20	        // December 15 to February 28
    21	        if (month == 12 && day >= 15) return true;
    22	        if (month == 1) return true;
    23	        if (month == 2) return true;
    24	
    25	        return false;
    26	    }
    27	
    28	    public static BigDecimal calculateNightlyPrice(BigDecimal baseRate, LocalDate date) {
    29	        BigDecimal price = baseRate;
    30	        if (isHighSeason(date)) {
    31	            price = baseRate.multiply(HIGH_SEASON_MULTIPLIER);
    32	        }
    33	        return roundHalfEven(price);
    34	    }
    35	
    36	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
    37	        BigDecimal subtotal = BigDecimal.ZERO;
    38	        LocalDate current = checkIn;
    39	
    40	        while (current.isBefore(checkOut)) {
    41	            BigDecimal nightPrice = calculateNightlyPrice(baseRate, current);
    42	            subtotal = subtotal.add(nightPrice);
    43	            current = current.plusDays(1);
    44	        }
    45	
    46	        return roundHalfEven(subtotal);
    47	    }
    48	
    49	    public static BigDecimal calculateDiscount(BigDecimal subtotal, boolean isNonRefundable) {
    50	        if (!isNonRefundable) {
    51	            return BigDecimal.ZERO;
    52	        }
    53	        BigDecimal discount = subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE);
    54	        return roundHalfEven(discount);
    55	    }
    56	
    57	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    58	        return roundHalfEven(subtotal.subtract(discount));
    59	    }
    60	
    61	    public static long calculateNights(LocalDate checkIn, LocalDate checkOut) {
    62	        return checkOut.toEpochDay() - checkIn.toEpochDay();
    63	    }
    64	
    65	    public static BigDecimal roundHalfEven(BigDecimal value) {
    66	        return value.setScale(SCALE, RoundingMode.HALF_EVEN);
    67	    }
    68	}

